// models/List.js
const mongoose = require('mongoose');
const listSchema = new mongoose.Schema({
  owner: { type: mongoose.Schema.Types.ObjectId, ref: 'User', required: true, index: true },
  name: { type: String, required: true, trim: true, maxlength: 100 },
  movies: [{ type: mongoose.Schema.Types.ObjectId, ref: 'Movie' }],
}, { timestamps: true });
listSchema.index({ owner: 1, name: 1 }, { unique: true, collation: { locale: 'en', strength: 2 } });
module.exports = mongoose.model('List', listSchema);

// routes/lists.js
// (separate file; mongoose is required the same way as in the model above)
const express = require('express');
const List = require('../models/List');
const Movie = require('../models/Movie');
const auth = require('../middleware/auth');

const router = express.Router();
router.use(auth);

const isDup = (e) => e && e.code === 11000;
const valid = (...ids) => ids.every((id) => mongoose.Types.ObjectId.isValid(id));
const own = (req) => ({ _id: req.params.listId, owner: req.user.id });
const notFound = (res) => res.status(404).json({ message: 'List not found' });

router.post('/', async (req, res, next) => {
  const name = String(req.body.name || '').trim();
  if (!name) return res.status(400).json({ message: 'List name is required' });
  try {
    res.status(201).json(await List.create({ owner: req.user.id, name }));
  } catch (e) {
    if (isDup(e)) return res.status(409).json({ message: 'You already have a list with this name' });
    next(e);
  }
});

router.get('/', async (req, res, next) => {
  try { res.json(await List.find({ owner: req.user.id }).sort({ createdAt: 1 }).populate('movies')); }
  catch (e) { next(e); }
});

router.put('/:listId', async (req, res, next) => {
  const name = String(req.body.name || '').trim();
  if (!name) return res.status(400).json({ message: 'List name is required' });
  if (!valid(req.params.listId)) return notFound(res);
  try {
    const list = await List.findOneAndUpdate(own(req), { name }, { new: true, runValidators: true });
    return list ? res.json(list) : notFound(res);
  } catch (e) {
    if (isDup(e)) return res.status(409).json({ message: 'You already have a list with this name' });
    next(e);
  }
});

router.delete('/:listId', async (req, res, next) => {
  if (!valid(req.params.listId)) return notFound(res);
  try {
    const r = await List.deleteOne(own(req));
    return r.deletedCount ? res.json({ message: 'List deleted' }) : notFound(res);
  } catch (e) { next(e); }
});

router.post('/:listId/movies', async (req, res, next) => {
  const { movieId } = req.body;
  if (!valid(req.params.listId)) return notFound(res);
  if (!valid(movieId)) return res.status(400).json({ message: 'Invalid movie id' });
  try {
    if (!(await Movie.exists({ _id: movieId }))) return res.status(404).json({ message: 'Movie not found' });
    const list = await List.findOneAndUpdate(own(req), { $addToSet: { movies: movieId } }, { new: true });
    return list ? res.json(list) : notFound(res);
  } catch (e) { next(e); }
});

router.delete('/:listId/movies/:movieId', async (req, res, next) => {
  if (!valid(req.params.listId, req.params.movieId)) return notFound(res);
  try {
    const list = await List.findOneAndUpdate(own(req), { $pull: { movies: req.params.movieId } }, { new: true });
    return list ? res.json(list) : notFound(res);
  } catch (e) { next(e); }
});

module.exports = router;
